import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/services/manga/storage/manga_progress_repository.dart';
import 'package:goanime/services/media/manga_progress_event_adapter.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  test('maps manga reading progress without changing page units', () {
    final progress = MangaChapterProgress(
      workId: 'work-1',
      canonicalChapterId: 'chapter-7',
      completed: false,
      lastReadAt: DateTime.parse('2026-08-24T08:00:00-03:00'),
      bookmark: MangaVariantBookmark(
        sourceId: 'source-1',
        mangaId: 'remote-work',
        chapterId: 'remote-chapter',
        pageIndex: 12,
        pageCount: 30,
      ),
    );

    final event = const MangaProgressEventAdapter().fromProgress(progress);

    expect(event.mediaKind, MediaKind.manga);
    expect(event.entityId, 'work-1');
    expect(event.unitId, 'chapter-7');
    expect(event.updatedAt, DateTime.utc(2026, 8, 24, 11));
    expect(event.completed, isFalse);
    expect(event.payload.sourceId, 'source-1');
    expect(event.payload.mangaId, 'remote-work');
    expect(event.payload.chapterId, 'remote-chapter');
    expect(event.payload.pageIndex, 12);
    expect(event.payload.pageCount, 30);
  });

  test(
    'logical manga progress remains valid when no physical bookmark exists',
    () {
      final progress = MangaChapterProgress(
        workId: 'work-1',
        canonicalChapterId: 'chapter-8',
        completed: true,
        lastReadAt: DateTime.utc(2026, 8, 24, 12),
      );

      final event = const MangaProgressEventAdapter().fromProgress(progress);

      expect(event.completed, isTrue);
      expect(event.payload.sourceId, isNull);
      expect(event.payload.pageIndex, isNull);
      expect(event.payload.pageCount, isNull);
    },
  );
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/services/media/manga_user_state_sync_sink.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  test(
    'accepts Manga events while declaring there is no remote backend',
    () async {
      const sink = MangaUserStateSyncSink();
      final event = UserMediaStateEvent<dynamic>(
        mediaKind: MediaKind.manga,
        entityId: 'manga-1',
        category: UserMediaStateCategory.progress,
        updatedAt: DateTime.utc(2026, 8, 24, 13),
        tombstone: false,
        partial: true,
        payload: 'local-progress',
      );

      expect(sink.mediaKind, MediaKind.manga);
      expect(sink.supportsRemoteBackend, isFalse);
      await expectLater(
        sink.sync(<UserMediaStateEvent<dynamic>>[event]),
        completes,
      );
    },
  );

  test('rejects Anime events instead of pretending to sync them', () async {
    const sink = MangaUserStateSyncSink();
    final event = UserMediaStateEvent<dynamic>(
      mediaKind: MediaKind.anime,
      entityId: 'anime-1',
      category: UserMediaStateCategory.library,
      updatedAt: DateTime.utc(2026, 8, 24, 13),
      tombstone: false,
      partial: true,
      payload: 'anime',
    );

    await expectLater(
      sink.sync(<UserMediaStateEvent<dynamic>>[event]),
      throwsArgumentError,
    );
  });
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/models/unified_anime_model.dart';
import 'package:goanime/services/source/episode_cache_repository.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  test('EpisodeCacheRepository obeys CachePolicy TTL', () async {
    final cache = EpisodeCacheRepository(
      policy: () =>
          const CachePolicy(ttl: Duration(milliseconds: 20), maxEntries: 4),
    );

    cache.saveMemory('one', const <UnifiedEpisode>[]);
    expect(cache.getFreshMemory('one'), isNotNull);

    await Future<void>.delayed(const Duration(milliseconds: 30));
    expect(cache.getFreshMemory('one'), isNull);
  });

  test('EpisodeCacheRepository obeys CachePolicy LRU capacity', () {
    final cache = EpisodeCacheRepository(
      policy: () => const CachePolicy(ttl: Duration(minutes: 5), maxEntries: 2),
    );

    cache.saveMemory('one', const <UnifiedEpisode>[]);
    cache.saveMemory('two', const <UnifiedEpisode>[]);
    expect(cache.getFreshMemory('one'), isNotNull);

    cache.saveMemory('three', const <UnifiedEpisode>[]);

    expect(cache.getFreshMemory('one'), isNotNull);
    expect(cache.getFreshMemory('two'), isNull);
    expect(cache.getFreshMemory('three'), isNotNull);
  });
}

